<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api,download}from'../api';
const list=ref<any[]>([]),total=ref(0),loading=ref(false),dialog=ref(false),editing=ref<number|null>(null),options=ref<any>({categories:[],levels:[]});
const query=reactive({page:1,page_size:20,keyword:'',year:undefined as number|undefined,achievement_type:'',level:''});
const blank=()=>({achievement_type:'教学成果',category:'课程建设',title:'',year:new Date().getFullYear(),achievement_date:null,level:'',rank:null,role:'',organization:'',certificate_no:'',score:0,description:'',remark:''});const form=reactive<any>(blank());
async function load(){loading.value=true;try{const{data}=await api.get('/achievements',{params:query});list.value=data.items;total.value=data.total}catch{ElMessage.error('成果列表加载失败')}finally{loading.value=false}}
function add(){Object.assign(form,blank());editing.value=null;dialog.value=true}function edit(row:any){Object.assign(form,row);editing.value=row.id;dialog.value=true}
async function save(){if(!form.title)return ElMessage.warning('请填写成果名称');if(editing.value)await api.put(`/achievements/${editing.value}`,form);else await api.post('/achievements',form);ElMessage.success('成果已保存');dialog.value=false;load()}
async function remove(row:any){await ElMessageBox.confirm(`确认删除“${row.title}”？`,'删除成果',{type:'warning'});await api.delete(`/achievements/${row.id}`);ElMessage.success('已删除');load()}
async function copy(row:any){await api.post(`/achievements/${row.id}/copy`);ElMessage.success('已创建副本');load()}
onMounted(async()=>{options.value=(await api.get('/settings/options')).data;load()})
</script>
<template><div class="panel"><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="搜索成果名称、单位或描述" style="width:260px" @keyup.enter="load"/><el-input-number v-model="query.year" :controls="false" placeholder="年度" style="width:110px"/><el-select v-model="query.achievement_type" clearable placeholder="成果类型" style="width:150px"><el-option v-for="x in options.categories" :key="x.name" :label="x.name" :value="x.name"/></el-select><el-select v-model="query.level" clearable placeholder="级别" style="width:130px"><el-option v-for="x in options.levels" :key="x" :value="x"/></el-select><el-button @click="query.page=1;load()">查询</el-button><div class="spacer"></div><el-button @click="download('/achievements/export/excel','成果清单.xlsx')">导出 Excel</el-button><el-button type="primary" @click="add">+ 新增成果</el-button></div><el-table v-loading="loading" :data="list" stripe><el-table-column prop="title" label="成果名称" min-width="280"><template #default="s"><b>{{s.row.title}}</b><div class="muted">{{s.row.category}}</div></template></el-table-column><el-table-column prop="achievement_type" label="类型" width="120"><template #default="s"><el-tag effect="plain">{{s.row.achievement_type}}</el-tag></template></el-table-column><el-table-column prop="year" label="年度" width="85"/><el-table-column prop="level" label="级别" width="105"/><el-table-column prop="rank" label="排名" width="75"><template #default="s">{{s.row.rank?'第 '+s.row.rank:'—'}}</template></el-table-column><el-table-column prop="score" label="积分" width="75"/><el-table-column label="操作" width="190" fixed="right"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link @click="copy(s.row)">复制</el-button><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><div style="display:flex;justify-content:flex-end;margin-top:18px"><el-pagination v-model:current-page="query.page" :total="total" :page-size="query.page_size" layout="total, prev, pager, next" @change="load"/></div></div><el-dialog v-model="dialog" :title="editing?'编辑成果':'新增成果'" width="720"><el-form :model="form" label-width="95"><div class="grid-2"><el-form-item label="成果类型" required><el-select v-model="form.achievement_type" @change="form.category=options.categories.find((x:any)=>x.name===form.achievement_type)?.children[0]||''"><el-option v-for="x in options.categories" :key="x.name" :value="x.name"/></el-select></el-form-item><el-form-item label="二级分类" required><el-select v-model="form.category"><el-option v-for="x in options.categories.find((x:any)=>x.name===form.achievement_type)?.children||[]" :key="x" :value="x"/></el-select></el-form-item></div><el-form-item label="成果名称" required><el-input v-model="form.title"/></el-form-item><div class="grid-2"><el-form-item label="年度" required><el-input-number v-model="form.year" :min="1950" :max="2200"/></el-form-item><el-form-item label="成果日期"><el-date-picker v-model="form.achievement_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="成果级别"><el-select v-model="form.level" clearable><el-option v-for="x in options.levels" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="本人排名"><el-input-number v-model="form.rank" :min="1"/></el-form-item><el-form-item label="角色"><el-input v-model="form.role"/></el-form-item><el-form-item label="积分"><el-input-number v-model="form.score" :precision="1"/></el-form-item></div><el-form-item label="组织单位"><el-input v-model="form.organization"/></el-form-item><el-form-item label="证书编号"><el-input v-model="form.certificate_no"/></el-form-item><el-form-item label="成果描述"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存成果</el-button></template></el-dialog></template>